app_private.normalize_invoice_adjustment.body:
DECLARE x jsonb; result jsonb:='[]'; price numeric; qty numeric; coeff numeric; idx integer:=0;
  service uuid; item_type public.invoice_item_type; cls text; prev numeric; curr numeric;
BEGIN
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)=0 OR jsonb_array_length(p_items)>500 THEN
    RAISE EXCEPTION 'Hóa đơn cần 1–500 hạng mục hợp lệ' USING ERRCODE='22023';
  END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    idx:=idx+1;
    IF jsonb_typeof(x) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Hạng mục phải là object' USING ERRCODE='22023'; END IF;
    IF jsonb_typeof(x->'description') IS DISTINCT FROM 'string' OR length(btrim(x->>'description'))=0 THEN
      RAISE EXCEPTION 'Hạng mục cần mô tả hợp lệ' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(x) k WHERE k NOT IN ('id','invoice_id','organization_id','created_at','updated_at',
      'service_id','type','description','unit_price','quantity','coefficient','amount','previous_reading','current_reading','from_date','to_date','sort_order','accounting_class')) THEN
      RAISE EXCEPTION 'Hạng mục chứa trường không được hỗ trợ; vui lòng tải lại' USING ERRCODE='22023'; END IF;
    BEGIN
      price:=coalesce((x->>'unit_price')::numeric,0); qty:=coalesce((x->>'quantity')::numeric,1); coeff:=coalesce((x->>'coefficient')::numeric,1);
      prev:=nullif(x->>'previous_reading','')::numeric; curr:=nullif(x->>'current_reading','')::numeric;
      item_type:=coalesce(nullif(x->>'type',''),'OTHER')::public.invoice_item_type;
      service:=nullif(x->>'service_id','')::uuid;
      cls:=x->>'accounting_class';
      IF cls IS NULL OR cls NOT IN ('REVENUE','DEPOSIT','NON_PNL')
        OR price<0 OR qty<0 OR coeff<0 OR price::text IN ('NaN','Infinity','-Infinity')
        OR qty::text IN ('NaN','Infinity','-Infinity') OR coeff::text IN ('NaN','Infinity','-Infinity')
        OR prev<0 OR curr<0 OR prev::text IN ('NaN','Infinity','-Infinity') OR curr::text IN ('NaN','Infinity','-Infinity')
        OR price*qty*coeff>=10000000000000 THEN
        RAISE EXCEPTION 'Giá, số lượng, hệ số hoặc phân loại hạng mục không hợp lệ' USING ERRCODE='22023';
      END IF;
      result:=result || jsonb_build_array(jsonb_build_object(
        'id',nullif(x->>'id','')::uuid,'type',item_type,'service_id',service,'description',x->>'description','unit_price',price,'quantity',qty,'coefficient',coeff,
        'amount',round(price*qty*coeff,2),'accounting_class',cls,'previous_reading',prev,'current_reading',curr,
        'from_date',nullif(x->>'from_date','')::date,'to_date',nullif(x->>'to_date','')::date,'sort_order',coalesce((x->>'sort_order')::integer,idx)));
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION 'Giá trị hạng mục không hợp lệ; vui lòng kiểm tra lại' USING ERRCODE='22023';
    END;
    IF service IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.services s WHERE s.id=service AND s.organization_id=p_organization_id AND s.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'Dịch vụ không thuộc tổ chức của hóa đơn' USING ERRCODE='42501';
    END IF;
  END LOOP;
  RETURN result;
END

app_private.require_building_perm_v1.body:
DECLARE
  v_keys text := array_to_string(p_permission_keys, '|');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION '[THIEU_QUYEN] Bạn chưa đăng nhập.' USING ERRCODE = '42501';
  END IF;
  IF coalesce(cardinality(p_permission_keys), 0) = 0
     OR EXISTS (SELECT 1 FROM unnest(p_permission_keys) k WHERE k IS NULL OR k !~ '^[a-z_]+\.[a-z_]+$') THEN
    RAISE EXCEPTION 'require_building_perm_v1: khoá quyền không hợp lệ (%)', v_keys USING ERRCODE = '22023';
  END IF;
  IF app_private.has_building_perm_v1(p_building_id, VARIADIC p_permission_keys) THEN
    RETURN;
  END IF;
  RAISE EXCEPTION '[THIEU_QUYEN:%] Bạn không có quyền % ở toà nhà này.', v_keys, coalesce(nullif(btrim(p_viec), ''), v_keys)
    USING ERRCODE = '42501',
          HINT = format('Cần quyền %s ở toà này (giống nút trên web). Nhờ chủ hoặc quản trị cấp quyền trong Phân quyền.',
                        replace(v_keys, '|', ' hoặc '));
END

public.cancel_invoice_with_credit_v1.body:
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_contract_id uuid;
  v_invoice public.invoices%ROWTYPE;
  v_credit jsonb;
BEGIN
  -- RENT_SUPPORT_LIFECYCLE_LOCK_V1
  PERFORM app_private.invoice_rent_support_lock_v1(p_invoice_id);
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT invoice_row.contract_id INTO v_contract_id
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id;
  IF v_contract_id IS NOT NULL THEN
    PERFORM 1 FROM public.contracts contract_row
    WHERE contract_row.id = v_contract_id FOR UPDATE;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF NOT app_private.can_edit_invoice_building_v1(v_invoice.building_id) THEN
    RAISE EXCEPTION 'Missing permission to cancel invoice'
      USING ERRCODE = '42501';
  END IF;
  PERFORM app_private.require_building_perm_v1(v_invoice.building_id, 'huỷ hoá đơn', 'invoices.cancel', 'invoices.delete'); -- [q26] kiểm quyền máy chủ khớp web
  IF v_invoice.status = 'CANCELLED' THEN
    RETURN jsonb_build_object(
      'invoice', to_jsonb(v_invoice),
      'credit', NULL,
      'noop', true
    );
  END IF;
  -- H1.1 (rà soát 15/09): hàng rào status/paid_amount phải nằm Ở ĐÂY.
  -- Trước bản này, `canCancelInvoice` bên client là hàng rào DUY NHẤT: gọi thẳng
  -- PostgREST là huỷ được hoá đơn đã thu tiền, và restore sau đó trả về APPROVED
  -- thay vì PARTIAL_PAID — số đã thu vẫn còn nhưng trạng thái nói ngược lại.
  -- Cùng một luật với soft_delete_invoice_with_credit_v1 đã có sẵn ngay dưới.
  -- Super admin KHÔNG đi đường này: họ có super_admin_force_cancel_invoice_with_credit_v1
  -- (hàm đó tự kiểm payment và unwind credit trước khi huỷ).
  IF v_invoice.status NOT IN ('DRAFT', 'APPROVED')
     OR COALESCE(v_invoice.paid_amount, 0) <> 0 THEN
    RAISE EXCEPTION
      'Không thể huỷ hoá đơn ở trạng thái này (chỉ huỷ được hoá đơn nháp/đã duyệt và chưa thu đồng nào)';
  END IF;

  PERFORM app_private.assert_invoice_credit_cancellable_v1(p_invoice_id);
  v_credit := app_private.reverse_invoice_customer_credit_v1(
    v_actor, p_invoice_id, 'Cancel invoice and restore applied customer credit', v_key
  );

  PERFORM app_private.begin_accounting_chain_write_v1();
  UPDATE public.invoices
     SET status = 'CANCELLED'
   WHERE id = p_invoice_id
   RETURNING * INTO v_invoice;
  PERFORM app_private.end_accounting_chain_write_v1();

  RETURN jsonb_build_object(
    'invoice', to_jsonb(v_invoice),
    'credit', v_credit,
    'noop', false
  );
END;

public.restore_invoice_with_credit_v1.body:
DECLARE
  v_actor uuid := auth.uid();
  v_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_contract_id uuid;
  v_invoice public.invoices%ROWTYPE;
  v_active_count integer;
  v_restore_amount numeric(15,2);
  v_restore_fingerprint text;
  v_apply_key text;
  v_credit jsonb;
BEGIN
  -- RENT_SUPPORT_LIFECYCLE_LOCK_V1
  PERFORM app_private.invoice_rent_support_lock_v1(p_invoice_id);
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF v_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' THEN
    RAISE EXCEPTION 'Invalid idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT invoice_row.contract_id INTO v_contract_id
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id;
  IF v_contract_id IS NOT NULL THEN
    PERFORM 1 FROM public.contracts contract_row
    WHERE contract_row.id = v_contract_id FOR UPDATE;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices invoice_row
  WHERE invoice_row.id = p_invoice_id
    AND invoice_row.deleted_at IS NULL
  FOR UPDATE;
  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42501';
  END IF;
  IF NOT app_private.can_edit_invoice_building_v1(v_invoice.building_id) THEN
    RAISE EXCEPTION 'Missing permission to restore invoice'
      USING ERRCODE = '42501';
  END IF;
  PERFORM app_private.require_building_perm_v1(v_invoice.building_id, 'khôi phục hoá đơn đã huỷ', 'invoices.cancel', 'invoices.delete'); -- [q26] kiểm quyền máy chủ khớp web
  IF v_invoice.status = 'APPROVED' THEN
    RETURN jsonb_build_object(
      'invoice', to_jsonb(v_invoice),
      'credit', NULL,
      'noop', true
    );
  END IF;
  IF v_invoice.status <> 'CANCELLED' THEN
    RAISE EXCEPTION 'Only cancelled invoices can be restored'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_active_count
  FROM public.customer_credit_applications application_row
  WHERE application_row.invoice_id = p_invoice_id
    AND application_row.reversed_at IS NULL;

  SELECT COALESCE(sum(application_row.amount), 0)::numeric(15,2),
         md5(COALESCE(string_agg(
           application_row.id::text, ',' ORDER BY application_row.id
         ), ''))
    INTO v_restore_amount, v_restore_fingerprint
  FROM public.customer_credit_applications application_row
  WHERE application_row.invoice_id = p_invoice_id
    AND application_row.reversed_at IS NOT NULL
    AND application_row.restored_at IS NULL;

  IF v_active_count > 0 AND v_restore_amount > 0 THEN
    RAISE EXCEPTION 'Invoice has mixed active and pending-restoration credit applications'
      USING ERRCODE = '55000';
  END IF;

  IF v_restore_amount > 0 THEN
    IF v_contract_id IS NULL THEN
      RAISE EXCEPTION 'Credit invoice has no contract' USING ERRCODE = '55000';
    END IF;
    v_apply_key := left(v_key, 150) || ':cycle:' || v_restore_fingerprint;
    v_credit := app_private.apply_customer_credit_fifo_v1(
      v_actor, v_contract_id, v_restore_amount, p_invoice_id,
      'INVOICE_DISCOUNT',
      'Reapply customer credit while restoring invoice', v_apply_key
    );
  ELSE
    v_credit := jsonb_build_object(
      'invoice_id', p_invoice_id,
      'applied_amount', 0,
      'applications', '[]'::jsonb
    );
  END IF;

  PERFORM app_private.begin_accounting_chain_write_v1();
  IF v_restore_amount > 0 THEN
    UPDATE public.customer_credit_applications
       SET restored_at = clock_timestamp(),
           restored_by = v_actor,
           restoration_idempotency_key = v_apply_key
     WHERE invoice_id = p_invoice_id
       AND reversed_at IS NOT NULL
       AND restored_at IS NULL;
  END IF;

  UPDATE public.invoices
     SET status = 'APPROVED',
         approved_at = clock_timestamp(),
         approved_by = v_actor
   WHERE id = p_invoice_id
   RETURNING * INTO v_invoice;
  PERFORM app_private.end_accounting_chain_write_v1();

  RETURN jsonb_build_object(
    'invoice', to_jsonb(v_invoice),
    'credit', v_credit,
    'noop', false
  );
END;

public.review_invoice_adjustment_v2.body:
DECLARE result public.invoice_adjustments%ROWTYPE; inv public.invoices%ROWTYPE; invoice_id uuid;
BEGIN
  SELECT a.invoice_id INTO invoice_id FROM public.invoice_adjustments a WHERE a.id=p_adjustment_id;
  SELECT * INTO inv FROM public.invoices i WHERE i.id=invoice_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR public.can_access_building(inv.building_id) IS DISTINCT FROM true OR public.can_do_on_building('invoices','approve',inv.building_id) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Không có quyền xác nhận kiểm tra' USING ERRCODE='42501'; END IF;
  SELECT * INTO result FROM public.invoice_adjustments WHERE id=p_adjustment_id FOR UPDATE;
  IF result.organization_id IS DISTINCT FROM inv.organization_id THEN RAISE EXCEPTION 'Điều chỉnh không thuộc tổ chức' USING ERRCODE='42501'; END IF;
  IF p_expected_revision IS DISTINCT FROM inv.adjustment_revision OR result.revision IS DISTINCT FROM inv.adjustment_revision THEN
    RAISE EXCEPTION 'Hóa đơn đã có phiên bản mới; vui lòng tải lại trước khi kiểm tra' USING ERRCODE='PT409'; END IF;
  IF result.review_status='CHECKED' THEN RETURN result; END IF;
  UPDATE public.invoice_adjustments SET review_status='CHECKED',checked_by=auth.uid(),checked_at=clock_timestamp() WHERE id=p_adjustment_id RETURNING * INTO result;
  UPDATE public.invoices SET adjustment_review_status='CHECKED',updated_at=clock_timestamp() WHERE id=inv.id;
  RETURN result;
END
